def encrypt_token_v1(token: str, key: bytes) -> str:
    import base64
    from hashlib import sha256
    cipher_key = sha256(key).digest()
    padded = token.ljust(32, " ")
    encrypted = bytes([b ^ cipher_key[i % 32] for i, b in enumerate(padded.encode())])
    return base64.b64encode(encrypted).decode()

